class CSBMaster {
	struct csb_op {
		int is_ext;
		int write;
		int tries;
		int reading;
		uint32_t addr;
		uint32_t mask;
		uint32_t data;
	};

	std::queue<csb_op> opq;

	VNV_nvdla *dla;

	int _test_passed;
	uint32_t intr_status_clear_mask;

public:
	CSBMaster(VNV_nvdla *_dla) {
		dla = _dla;

		dla->csb2nvdla_valid = 0;
		_test_passed = 1;
		intr_status_clear_mask = 0;
	}

	void read(uint32_t addr, uint32_t mask, uint32_t data) {
		csb_op op;

		op.is_ext = 0;
		op.write = 0;
		op.addr = addr;
		op.mask = mask;
		op.data = data;
		op.tries = (addr == 0xffff0003) ? 100000 : 10;
		op.reading = 0;

		opq.push(op);
	}

	void write(uint32_t addr, uint32_t data) {
		csb_op op;

		op.is_ext = 0;
		op.write = 1;
		op.addr = addr;
		op.data = data;

		opq.push(op);
	}

	void ext_event(int ext) {
		csb_op op;

		op.is_ext = ext;
		opq.push(op);
	}

	int eval(int noop) {
		if (dla->nvdla2csb_wr_complete)
			VPRINTF("(%lu) write complete from CSB\n", ticks);

		dla->csb2nvdla_valid = 0;
		if (opq.empty())
			return 0;

		csb_op &op = opq.front();

		if (op.is_ext && !noop) {
			int ext = op.is_ext;
			opq.pop();

			return ext;
		}

		if (!op.write && op.reading && dla->nvdla2csb_valid) {
			VPRINTF("(%lu) read response from nvdla: %08x\n", ticks, dla->nvdla2csb_data);

			uint32_t masked_data = dla->nvdla2csb_data & op.mask;
			uint32_t expected_data = op.data & op.mask;
			int soft_intr_match = 0;

			if ((op.addr == 0xffff0003) && (masked_data != expected_data)) {
				soft_intr_match =
					((expected_data == 0x00010000) && (dla->nvdla2csb_data & 0x00040000)) ||
					((expected_data == 0x00020000) && (dla->nvdla2csb_data & 0x00080000));
				if (soft_intr_match)
					VPRINTF("(%lu) accepting CDMA weight interrupt while waiting for CDMA data interrupt\n", ticks);
			}

			if (!soft_intr_match && (masked_data != expected_data)) {
				op.reading = 0;
				op.tries--;
				VPRINTF("(%lu) invalid response -- trying again\n", ticks);
				if (!op.tries) {
					printf("(%lu) ERROR: timed out reading response\n", ticks);
					_test_passed = 0;
					opq.pop();
				}
			} else {
				if (op.addr == 0xffff0003)
					intr_status_clear_mask = op.mask & op.data;
				opq.pop();
			}
		}

		if (!op.write && op.reading)
			return 0;

		if (noop)
			return 0;

		if (!dla->csb2nvdla_ready) {
			VPRINTF("(%lu) CSB stalled...\n", ticks);
			return 0;
		}

		if (op.write) {
			uint32_t write_data = op.data;
			if ((op.addr == 0xffff0003) && (op.data == 0xffffffff) && intr_status_clear_mask) {
				write_data = intr_status_clear_mask;
				intr_status_clear_mask = 0;
			}

			dla->csb2nvdla_valid = 1;
			dla->csb2nvdla_addr = op.addr;
			dla->csb2nvdla_wdat = write_data;
			dla->csb2nvdla_write = 1;
			dla->csb2nvdla_nposted = 0;
			VPRINTF("(%lu) write to nvdla: addr %08x, data %08x\n", ticks, op.addr, write_data);
			opq.pop();
		} else {
			dla->csb2nvdla_valid = 1;
			dla->csb2nvdla_addr = op.addr;
			dla->csb2nvdla_write = 0;
			VPRINTF("(%lu) read from nvdla: addr %08x\n", ticks, op.addr);

			op.reading = 1;
		}

		return 0;
	}

	bool done() {
		return opq.empty();
	}

	int test_passed() {
		return _test_passed;
	}
};

