template <typename ADDRTYPE>
class AXIResponder {
public:
	struct connections {
		uint8_t *aw_awvalid;
		uint8_t *aw_awready;
		uint8_t *aw_awid;
		uint8_t *aw_awlen;
		ADDRTYPE *aw_awaddr;

		uint8_t *w_wvalid;
		uint8_t *w_wready;
		uint32_t *w_wdata;
		uint64_t *w_wstrb;
		uint8_t *w_wlast;

		uint8_t *b_bvalid;
		uint8_t *b_bready;
		uint8_t *b_bid;

		uint8_t *ar_arvalid;
		uint8_t *ar_arready;
		uint8_t *ar_arid;
		uint8_t *ar_arlen;
		ADDRTYPE *ar_araddr;

		uint8_t *r_rvalid;
		uint8_t *r_rready;
		uint8_t *r_rid;
		uint8_t *r_rlast;
		uint32_t *r_rdata;
	};

private:

#define AXI_BLOCK_SIZE 4096
#define AXI_WIDTH 512

	const static int AXI_R_LATENCY = 32;
	const static int AXI_R_DELAY = 0;

	struct axi_r_txn {
		int rvalid;
		int rlast;
		uint32_t rdata[AXI_WIDTH / 32];
		uint8_t rid;
	};
	std::queue<axi_r_txn> r_fifo;
	std::queue<axi_r_txn> r0_fifo;

	struct axi_aw_txn {
		uint8_t awid;
		uint32_t awaddr;
		uint8_t awlen;
	};
	std::queue<axi_aw_txn> aw_fifo;

	struct axi_w_txn {
		uint32_t wdata[AXI_WIDTH / 32];
		uint64_t wstrb;
		uint8_t wlast;
	};
	std::queue<axi_w_txn> w_fifo;

	struct axi_b_txn {
		uint8_t bid;
	};
	std::queue<axi_b_txn> b_fifo;

	std::map<uint32_t, std::vector<uint8_t> > ram;

	struct connections dla;
	const char *name;
	uint64_t read_bursts;
	uint64_t read_beats;
	uint64_t read_resp_beats;
	uint64_t write_bursts;
	uint64_t write_beats;
	uint64_t write_resp_beats;
	uint64_t last_read_addr;
	uint64_t last_write_addr;

public:	
	AXIResponder(struct connections _dla, const char *_name) {
		dla = _dla;

		*dla.aw_awready = 1;
		*dla.w_wready = 1;
		*dla.b_bvalid = 0;
		*dla.ar_arready = 1;
		*dla.r_rvalid = 0;

		name = _name;
		read_bursts = 0;
		read_beats = 0;
		read_resp_beats = 0;
		write_bursts = 0;
		write_beats = 0;
		write_resp_beats = 0;
		last_read_addr = 0;
		last_write_addr = 0;

		/* add some latency... */
		for (int i = 0; i < AXI_R_LATENCY; i++) {
			axi_r_txn txn;

			txn.rvalid = 0;
			txn.rvalid = 0;
			txn.rid = 0;
			txn.rlast = 0;
			for (int i = 0; i < AXI_WIDTH / 32; i++) {
				txn.rdata[i] = 0xAAAAAAAA;
			}

			r0_fifo.push(txn);
		}
	}

	uint8_t read(uint32_t addr) {
		ram[addr / AXI_BLOCK_SIZE].resize(AXI_BLOCK_SIZE, 0);
		return ram[addr / AXI_BLOCK_SIZE][addr % AXI_BLOCK_SIZE];
	}

	void write(uint32_t addr, uint8_t data) {
		ram[addr / AXI_BLOCK_SIZE].resize(AXI_BLOCK_SIZE, 0);
		ram[addr / AXI_BLOCK_SIZE][addr % AXI_BLOCK_SIZE] = data;
	}

	void eval() {
		/* write request */
		if (*dla.aw_awvalid && *dla.aw_awready) {
			VPRINTF("(%lu) %s: write request from dla, addr %08lx id %d\n", ticks, name, *dla.aw_awaddr, *dla.aw_awid);

			axi_aw_txn txn;

			txn.awid = *dla.aw_awid;
			txn.awaddr = *dla.aw_awaddr & ~(ADDRTYPE)(AXI_WIDTH / 8 - 1);
			txn.awlen = *dla.aw_awlen;
			aw_fifo.push(txn);
			write_bursts++;
			last_write_addr = txn.awaddr;

			*dla.aw_awready = 0;
		} else
			*dla.aw_awready = 1;

		/* write data */
		if (*dla.w_wvalid) {
			VPRINTF("(%lu) %s: write data from dla (%08x %08x...)\n", ticks, name, dla.w_wdata[0], dla.w_wdata[1]);

			axi_w_txn txn;

			for (int i = 0; i < AXI_WIDTH / 32; i++)
				txn.wdata[i] = dla.w_wdata[i];
			txn.wstrb = *dla.w_wstrb;
			txn.wlast = *dla.w_wlast;
			w_fifo.push(txn);
		}

		/* read request */
		if (*dla.ar_arvalid && *dla.ar_arready) {
			ADDRTYPE addr = *dla.ar_araddr & ~(ADDRTYPE)(AXI_WIDTH / 8 - 1);
			uint8_t len = *dla.ar_arlen;
			uint32_t beats = len + 1;

			VPRINTF("(%lu) %s: read request from dla, addr %08lx burst %d id %d\n", ticks, name, *dla.ar_araddr, *dla.ar_arlen, *dla.ar_arid);
			read_bursts++;
			read_beats += beats;
			last_read_addr = addr;

			do {
				axi_r_txn txn;

				txn.rvalid = 1;
				txn.rlast = len == 0;
				txn.rid = *dla.ar_arid;

				for (int i = 0; i < AXI_WIDTH / 32; i++) {
					uint32_t da = read(addr + i * 4) + 
					              (read(addr + i * 4 + 1) << 8) + 
					              (read(addr + i * 4 + 2) << 16) + 
					              (read(addr + i * 4 + 3) << 24);
					txn.rdata[i] = da;
				}

				r_fifo.push(txn);

				addr += AXI_WIDTH / 8;
			} while (len--);

			axi_r_txn txn;

			txn.rvalid = 0;
			txn.rid = 0;
			txn.rlast = 0;
			for (int i = 0; i < AXI_WIDTH / 32; i++) {
				txn.rdata[i] = 0x55555555;
			}

			for (int i = 0; i < AXI_R_DELAY; i++)
				r_fifo.push(txn);

			*dla.ar_arready = 0;
		} else
			*dla.ar_arready = 1;

		/* now handle the write FIFOs ... */
		if (!aw_fifo.empty() && !w_fifo.empty()) {
			axi_aw_txn &awtxn = aw_fifo.front();
			axi_w_txn &wtxn = w_fifo.front();

			if (wtxn.wlast != (awtxn.awlen == 0)) {
				VPRINTF("(%lu) %s: wlast / awlen mismatch\n", ticks, name);
				abort();
			}

			for (int i = 0; i < AXI_WIDTH / 8; i++) {
				if (!((wtxn.wstrb >> i) & 1))
					continue;

				write(awtxn.awaddr + i, (wtxn.wdata[i / 4] >> ((i % 4) * 8)) & 0xFF);
			}
			write_beats++;
			last_write_addr = awtxn.awaddr;


			if (wtxn.wlast) {
				VPRINTF("(%lu) %s: write, last tick\n", ticks, name);
				aw_fifo.pop();

				axi_b_txn btxn;
				btxn.bid = awtxn.awid;
				b_fifo.push(btxn);
			} else {
				VPRINTF("(%lu) %s: write, ticks remaining\n", ticks, name);

				awtxn.awlen--;
				awtxn.awaddr += AXI_WIDTH / 8;
			}

			w_fifo.pop();
		}

		/* read response */
		if (!r_fifo.empty()) {
			axi_r_txn &txn = r_fifo.front();

			r0_fifo.push(txn);
			r_fifo.pop();
		} else {
			axi_r_txn txn;

			txn.rvalid = 0;
			txn.rid = 0;
			txn.rlast = 0;
			for (int i = 0; i < AXI_WIDTH / 32; i++) {
				txn.rdata[i] = 0xAAAAAAAA;
			}

			r0_fifo.push(txn);
		}

		*dla.r_rvalid = 0;
		if (*dla.r_rready && !r0_fifo.empty()) {
			axi_r_txn &txn = r0_fifo.front();

			*dla.r_rvalid = txn.rvalid;
			*dla.r_rid = txn.rid;
			*dla.r_rlast = txn.rlast;
			for (int i = 0; i < AXI_WIDTH / 32; i++) {
				dla.r_rdata[i] = txn.rdata[i];
			}

			if (txn.rvalid)
				VPRINTF("(%lu) %s: read push: id %d, da %08x %08x %08x %08x\n",
					ticks, name, txn.rid, txn.rdata[0], txn.rdata[1], txn.rdata[2], txn.rdata[3]);
			if (txn.rvalid)
				read_resp_beats++;

			r0_fifo.pop();
		}

		/* write response */
		*dla.b_bvalid = 0;
		if (*dla.b_bready && !b_fifo.empty()) {
			*dla.b_bvalid = 1;

			axi_b_txn &txn = b_fifo.front();
			*dla.b_bid = txn.bid;
			b_fifo.pop();
			write_resp_beats++;
		}
	}

	void report_progress() {
		printf(" %s_rb=%lu %s_rbeat=%lu %s_rrsp=%lu %s_raddr=0x%08lx %s_wb=%lu %s_wbeat=%lu %s_wrsp=%lu %s_waddr=0x%08lx"
			" %s_q_aw=%zu %s_q_w=%zu %s_q_b=%zu %s_q_r=%zu %s_sig_aw=%d/%d %s_sig_w=%d/%d %s_sig_b=%d/%d %s_sig_ar=%d/%d %s_sig_r=%d/%d",
			name, read_bursts, name, read_beats, name, read_resp_beats, name, last_read_addr,
			name, write_bursts, name, write_beats, name, write_resp_beats, name, last_write_addr,
			name, aw_fifo.size(), name, w_fifo.size(), name, b_fifo.size(), name, r_fifo.size(),
			name, *dla.aw_awvalid, *dla.aw_awready,
			name, *dla.w_wvalid, *dla.w_wready,
			name, *dla.b_bvalid, *dla.b_bready,
			name, *dla.ar_arvalid, *dla.ar_arready,
			name, *dla.r_rvalid, *dla.r_rready);
	}
};

