	void axievent() {
		if (opq.empty()) {
			VPRINTF("extevent with nothing in the queue?\n");
			abort();
		}

		axi_op &op = opq.front();

		AXIResponder<uint64_t> *axi;
		if ((op.addr & 0xF0000000) == 0x50000000)
			axi = axi_cvsram;
		else if ((op.addr & 0xF0000000) == 0x80000000)
			axi = axi_dbb;
		else {
			VPRINTF("AXI event to bad offset\n");
			abort();
		}

		switch(op.opcode) {
		case AXI_LOADMEM: {
			const uint8_t *buf = op.buf;

			VPRINTF("AXI: loading memory at 0x%08x\n", op.addr);
			while (op.len) {
				axi->write(op.addr, *buf);
				buf++;
				op.addr++;
				op.len--;
			}
			break;
		}
		case AXI_DUMPMEM: {
			int fd;
			const uint8_t *buf = op.buf;
			int matched = 1;

			VPRINTF("AXI: dumping memory to %s\n", op.fname);
			fd = creat(op.fname, 0666);
			if (!fd) {
				perror("creat(dumpmem)");
				break;
			}
			while (op.len) {
				uint8_t da = axi->read(op.addr);
				write(fd, &da, 1);
				if (da != *buf && matched) {
					printf("AXI: FAIL: mismatch at memory address %08x (exp 0x%02x, got 0x%02x), and maybe others too\n", op.addr, *buf, da);
					matched = 0;
					_test_passed = 0;
				}
				buf++;
				op.addr++;
				op.len--;
			}
			close(fd);

			if (matched)
				VPRINTF("AXI: memory dump matched reference\n");
			break;
		}
		default:
			abort();
		}

		opq.pop();
	}

	int test_passed() {
		return _test_passed;
	}
